// Estrai JSON dall'agente2 — prompt per Qwen-Image + formato dell'immagine
// Garantisce l'inquadratura a figura intera anche se il modello linguistico se ne dimentica.
const agentOutput = $input.first().json.output
  ?? $input.first().json.text
  ?? $input.first().json.content
  ?? '';

let sessionId, userPrompt = '';
try {
  const req = $('Estrai prompt + session_id').first().json;
  sessionId = req.session_id;
  userPrompt = String(req.prompt ?? '');
} catch (e) {
  sessionId = 'test_' + Date.now().toString();
}

let parsed;
try {
  const clean = agentOutput.replace(/```json|```/gi, '').trim();
  const match = clean.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('Nessun JSON trovato');
  parsed = JSON.parse(match[0]);
} catch (e) {
  console.log('JSON parse fallito, uso fallback. Output:', agentOutput.substring(0, 200));
  parsed = { flux_prompt: agentOutput.substring(0, 300) || userPrompt, object_name: 'object', style_tags: '' };
}
if (!parsed.flux_prompt) throw new Error(`flux_prompt mancante. Parsed: ${JSON.stringify(parsed)}`);

const type = String(parsed.subject_type ?? '').toLowerCase().trim();
let prompt = String(parsed.flux_prompt).trim();

// l'utente ha chiesto esplicitamente un dettaglio? (allora niente figura intera forzata)
const askedDetail = /\b(mezzo busto|busto|ritratto|primo piano|testa|volto|faccia|bust|portrait|head|close-?up)\b/i.test(userPrompt);
if (!askedDetail) {
  prompt = prompt
    .replace(/\b(portrait|bust|close-?up|headshot|upper[- ]body|half[- ]body|waist[- ]up|macro)( shot| view)?\b,?/gi, '')
    .replace(/\s+,/g, ',').replace(/\s{2,}/g, ' ').trim();
  if ((type === 'character' || type === 'creature') && !/full[- ]body/i.test(prompt))
    prompt = /^of\b/i.test(prompt) ? 'Full body shot ' + prompt : 'Full body shot of ' + prompt.charAt(0).toLowerCase() + prompt.slice(1);
  if (!/(nothing cropped|entire subject|fully visible)/i.test(prompt))
    prompt += ', entire subject fully visible with empty margin around it, nothing cropped';
  if (!/white background/i.test(prompt)) prompt += ', isolated on a pure white background, soft even studio lighting';
}

// formato: verticale per i personaggi, orizzontale per animali e veicoli (stessi pixel di 800×800, multipli di 16)
const SIZES = { tall: [704, 928], wide: [928, 704], square: [800, 800] };
let aspect = String(parsed.aspect ?? '').toLowerCase().trim();
if (!SIZES[aspect]) aspect = type === 'character' ? 'tall' : (type === 'creature' || type === 'vehicle') ? 'wide' : 'square';
if (askedDetail) aspect = 'square';
const [width, height] = SIZES[aspect];

return [{ json: {
  flux_prompt: prompt,
  object_name: parsed.object_name ?? 'object',
  style_tags: parsed.style_tags ?? '',
  subject_type: type || 'object',
  aspect, width, height,
  session_id: sessionId,
  seed: Math.floor(Math.random() * 9999999999)
} }];

// Polling del GLB legato a QUESTA esecuzione (tramite prompt_id di ComfyUI)
const history   = $input.first().json;
const agentData = $('Dati richiesta 3D1').first().json;
const promptId  = $('Registra prompt_id').first().json.prompt_id;
if (!promptId) throw new Error('prompt_id mancante nella risposta di ComfyUI');

// Annullata dall'utente? (riga scritta dal workflow quest-cancel)
const cancelRow = $('Annullata? (polling)1').first().json;
if (cancelRow?.session_id && cancelRow.session_id === agentData.session_id) {
  throw new Error(`Richiesta annullata dall'utente (sessione ${agentData.session_id})`);
}

const attempts = $runIndex + 1;
const MAX_ATTEMPTS = 400;         // con Wait da 3 s = 15 minuti

const entry = history[promptId];
if (entry?.status?.status_str === 'error') {
  throw new Error(`ComfyUI: esecuzione fallita o interrotta per ${promptId} — ${JSON.stringify(entry.status.messages ?? []).substring(0, 300)}`);
}

// Cerca il .glb (preferendo i file salvati, type "output")
const glbs = [];
for (const out of Object.values(entry?.outputs ?? {})) {
  for (const val of Object.values(out ?? {})) {
    if (!Array.isArray(val)) continue;
    for (const f of val) {
      if (typeof f?.filename === 'string' && f.filename.toLowerCase().endsWith('.glb')) glbs.push(f);
    }
  }
}
const glb = glbs.filter(f => (f.type ?? 'output') === 'output').at(-1) ?? glbs.at(-1) ?? null;

if (!glb) {
  if (entry?.status?.completed) {
    throw new Error(`Prompt ${promptId} completato ma nessun .glb trovato. Outputs: ${JSON.stringify(entry.outputs).substring(0, 400)}`);
  }
  if (attempts >= MAX_ATTEMPTS) throw new Error(`Timeout: nessun GLB per ${promptId} dopo ${attempts} tentativi`);
  return [{ json: { _ready: false, _attempts: attempts, prompt_id: promptId } }];
}

const host = '10.54.15.50';
const port = 8188;
const glbUrl = `http://${host}:${port}/view?filename=${encodeURIComponent(glb.filename)}`
  + `&type=${glb.type || 'output'}&subfolder=${encodeURIComponent(glb.subfolder ?? '')}`;

return [{ json: {
  _ready: true,
  _attempts: attempts,
  status: 'ready',
  glb_url: glbUrl,
  prompt_id: promptId,
  mode: $('Registra prompt_id').first().json.mode,
  object_name: agentData.object_name,
  session_id: agentData.session_id,
  flux_prompt: agentData.flux_prompt,
  message: 'Oggetto generato con successo!'
}}];

console.log('✅ Pipeline completata!');
console.log('GLB URL:', $json.glb_url);
console.log('Oggetto:', $json.object_name);
console.log('Tentativi:', $json._attempts);
return [$input.first()];

// Un solo webhook, due fasi: action = "image" (anteprima, ripeti, correzioni) | "model" (3D dall'immagine approvata)
// mode = "fast" (IDOL, predefinito) | "detailed" (Pixal3D) | "multiview" (Pixal3D multiview: 3 viste fronte/destra/retro)
const data = $input.first().json;
const b = data.body ?? data;

const action = String(b.action ?? 'image').toLowerCase() === 'model' ? 'model' : 'image';
const m = String(b.mode ?? 'fast').toLowerCase();
const mode = (m === 'detailed' || m === 'multiview') ? m : 'fast';
const msg = (b.prompt ?? data.chatInput ?? data.input ?? data.message ?? 'una sedia medievale').toString();
const sessionId = b.session_id ?? ('test_' + Date.now().toString());

return [{ json: {
  action,
  mode,
  prompt: msg.trim(),
  session_id: sessionId,
  image_path: b.image_path ?? '',
  image_paths: Array.isArray(b.image_paths) ? b.image_paths.filter(x => x) : [],
  object_name: b.object_name ?? '',
  flux_prompt: b.flux_prompt ?? '',
  seed: b.seed ?? ''
} }];

const items = $input.all();
const agentData = $('Dati richiesta 3D1').first().json;

// Una immagine per item (multivista: fronte, destra, retro); il binary del nodo HTTP è in "data"
const list = [];
for (let i = 0; i < items.length; i++) {
  const keys = Object.keys(items[i].binary ?? {});
  if (keys.length === 0) throw new Error(`Nessuna immagine scaricata per la vista ${i}`);
  const buffer = await this.helpers.getBinaryDataBuffer(i, keys[0]);
  list.push(buffer.toString('base64'));
  console.log(`Immagine ${i} convertita: ${Math.round(buffer.length / 1024)}KB`);
}

return [{ json: {
  image_base64: list[0],
  images_base64: list,
  mode: agentData.mode,
  session_id: agentData.session_id,
  object_name: agentData.object_name,
  seed: agentData.seed
} }];

// Anteprima: percorso dell'immagine su ComfyUI (relativo, l'host lo mette Unity)
const item = $input.first();
const a = $("Estrai JSON dall\'agente").first().json;

let filename = null;
for (const bin of Object.values(item.binary ?? {})) {
  const f = String(bin?.fileName ?? '');
  if (f.toLowerCase().endsWith('.png') && f.startsWith('ar_' + a.session_id)) { filename = f; break; }
}
if (!filename) filename = `ar_${a.session_id}_00001_.png`;   // SaveImage: prefisso ar_<session_id>

return [{ json: {
  status: 'preview',
  session_id: a.session_id,
  image_path: `/view?filename=${encodeURIComponent(filename)}&type=output&subfolder=`,
  object_name: a.object_name,
  flux_prompt: a.flux_prompt,
  seed: String(a.seed)
} }];

// Fase 3D: dati delle immagini approvate in anteprima (multivista: 3 immagini = 3 item, le altre modalità: 1)
const d = $input.first().json;
if (!d.image_path) throw new Error('image_path mancante: action=model richiede l\'immagine approvata');
const paths = (d.mode === 'multiview' && d.image_paths.length >= 3) ? d.image_paths.slice(0, 3) : [d.image_path];
if (d.mode === 'multiview' && paths.length < 3) throw new Error('Multivista: servono 3 immagini (image_paths)');
return paths.map((p, i) => ({ json: {
  session_id: d.session_id,
  mode: d.mode,
  image_path: p,
  view_index: i,
  object_name: d.object_name || 'object',
  flux_prompt: d.flux_prompt || '',
  seed: d.seed
} }));

// Multivista: 3 prompt (fronte, destra, retro) con lo stesso seed → 3 esecuzioni di Qwen Image Turbo
const a = $input.first().json;
let base = String(a.flux_prompt || '')
  .replace(/,?\s*(elevated\s+)?(three[- ]quarter|3\/4)(\s+side)?\s+(view|angle|perspective)( from above| slightly from above)?/gi, '')
  .replace(/,?\s*facing the camera/gi, '')
  .replace(/\s+,/g, ',').replace(/\s{2,}/g, ' ').trim();
const VIEWS = [
  { view: 'front', text: 'strictly the FRONT view, the camera looks at the subject straight on from the front, orthographic look, symmetrical framing' },
  { view: 'right', text: "strictly the RIGHT SIDE view, the camera is exactly 90 degrees to the subject's right and sees its right profile, orthographic look" },
  { view: 'back',  text: 'strictly the BACK view, the camera is directly behind the subject and sees it from behind, orthographic look' },
];
const tail = ', same distance and same scale, subject centered and filling most of the frame, no perspective distortion';
return VIEWS.map(v => ({ json: {
  session_id: a.session_id,
  view: v.view,
  flux_prompt: `${base}, ${v.text}${tail}`,
  base_prompt: a.flux_prompt,
  object_name: a.object_name,
  seed: a.seed,
  width: 1024, height: 1024
} }));

// Anteprima multivista: percorsi delle 3 immagini su ComfyUI (relativi, l'host lo mette Unity)
const items = $input.all();
const first = $('Prepara 3 viste').first().json;
const paths = items.map((it, i) => {
  const view = $('Prepara 3 viste').all()[i].json.view;
  let filename = null;
  for (const bin of Object.values(it.binary ?? {})) {
    const f = String(bin?.fileName ?? '');
    if (f.toLowerCase().endsWith('.png') && f.startsWith('ar_' + first.session_id + '_' + view)) { filename = f; break; }
  }
  if (!filename) filename = `ar_${first.session_id}_${view}_00001_.png`;
  return `/view?filename=${encodeURIComponent(filename)}&type=output&subfolder=`;
});
return [{ json: {
  status: 'preview',
  session_id: first.session_id,
  image_path: paths[0],
  image_paths: paths,
  object_name: first.object_name,
  flux_prompt: first.base_prompt,
  seed: String(first.seed)
} }];

