const r = $input.first().json;
if (!r.prompt_id) throw new Error('ComfyUI non ha accettato il grafo: ' + JSON.stringify(r).substring(0, 400));
return [{ json: { prompt_id: r.prompt_id, mode: $('Estrai prompt + session_id').first().json.mode } }];

// Annullamento per sessione: cerca nella coda di ComfyUI SOLO i job di questa sessione
// (i grafi salvano con prefisso "ar_<session_id>", anche "3d/ar_<session_id>"), così gli altri visori non vengono toccati.
const sid = String($('Webhook annulla').first().json.body?.session_id ?? '');
if (!sid) return [];
const q = $input.first().json ?? {};
const needle = 'ar_' + sid;
const jobs = [];
for (const [list, running] of [[q.queue_running, true], [q.queue_pending, false]]) {
  for (const item of (list ?? [])) {
    // item = [numero, prompt_id, grafo, extra_data, output]
    if (JSON.stringify(item[2] ?? {}).includes(needle)) jobs.push({ json: { prompt_id: item[1], running, session_id: sid } });
  }
}
return jobs;   // nessun job trovato = nulla da fermare (la riga in quest_cancel ferma comunque il polling)
